    }

    public async Task<TransactionResult> ReverseSupplierReturnCreditRefundAsync(ReverseSupplierReturnCreditRefundRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.PaymentReverse)) return TransactionResult.Failure("You are not authorized to reverse supplier-credit refunds."); if (string.IsNullOrWhiteSpace(request.Reason)) return TransactionResult.Failure("A reversal reason is required."); await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken); var refund = await db.SupplierReturnCreditRefunds.SingleOrDefaultAsync(item => item.Id == request.SupplierReturnCreditRefundId && item.CompanyId == companyId, cancellationToken);
        if (refund is null || refund.Status != "Posted") return TransactionResult.Failure("Only a posted supplier-credit refund can be reversed."); if (!string.Equals(refund.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The supplier-credit refund changed after it was opened. Refresh and review it again."); if (request.ReversalDate < refund.RefundDate) return TransactionResult.Failure("The reversal date cannot precede the refund date."); if (await IsInCompletedReconciliationAsync(db, refund.JournalEntryId, cancellationToken)) return TransactionResult.Failure("A reconciled supplier refund cannot be reversed until its bank reconciliation is reopened.");
        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken); var reversal = await PostInverseAsync(db, companyId, refund.JournalEntryId, request.ReversalDate, $"REV-{refund.Reference}", request.Reason.Trim(), refund.Id, "SupplierReturnCreditRefundReversal", refund.BankAccountId, cancellationToken, "Accounts Payable"); if (!reversal.Succeeded) return reversal; var shipment = await db.SupplierReturnShipments.SingleAsync(item => item.Id == refund.SupplierReturnShipmentId && item.CompanyId == companyId, cancellationToken); var authorization = await db.SupplierReturnAuthorizations.SingleAsync(item => item.Id == shipment.SupplierReturnAuthorizationId && item.CompanyId == companyId, cancellationToken); var bank = await db.BankAccounts.SingleAsync(item => item.Id == refund.BankAccountId && item.CompanyId == companyId, cancellationToken); refund.Status = "Reversed"; refund.ReversalJournalEntryId = reversal.Id; refund.ReversedByUserId = ResolveUserId(); refund.ReversedAtUtc = DateTimeOffset.UtcNow; refund.ReversalDate = request.ReversalDate; refund.ReversalReason = request.Reason.Trim(); refund.ConcurrencyToken = Guid.NewGuid().ToString("N"); shipment.RefundedAmount -= refund.Amount; shipment.ConcurrencyToken = Guid.NewGuid().ToString("N"); bank.CurrentBalance -= refund.Amount; bank.UnreconciledAmount += refund.Amount; bank.ConcurrencyToken = Guid.NewGuid().ToString("N"); (await db.Vendors.SingleAsync(item => item.Id == authorization.VendorId && item.CompanyId == companyId, cancellationToken)).OpenBalance -= refund.Amount; AddPurchasingAudit(db, companyId, "supplier-return.credit-refund.reversed", nameof(SupplierReturnCreditRefund), refund.Id, new { refund.Reference, refund.Amount, request.ReversalDate, reason = request.Reason.Trim() });
        try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The supplier refund changed while reversing. Refresh and try again."); }
        await transaction.CommitAsync(cancellationToken); return TransactionResult.Success(refund.Id);
    }

    public async Task<TransactionResult> ReverseSupplierReturnShipmentAsync(ReverseSupplierReturnShipmentRequest request, CancellationToken cancellationToken = default)
    {
        if (!HasPermission(BrassLedgerPermissions.PurchasingManage) || !HasPermission(BrassLedgerPermissions.PaymentReverse)) return TransactionResult.Failure("You are not authorized to reverse supplier-return shipments."); if (string.IsNullOrWhiteSpace(request.Reason)) return TransactionResult.Failure("A reversal reason is required."); await using var db = await dbContextFactory.CreateDbContextAsync(cancellationToken); var companyId = await ResolveCompanyIdAsync(db, cancellationToken); var shipment = await db.SupplierReturnShipments.SingleOrDefaultAsync(item => item.Id == request.SupplierReturnShipmentId && item.CompanyId == companyId, cancellationToken);
        if (shipment is null || shipment.Status != "Posted") return TransactionResult.Failure("Only a posted supplier-return shipment can be reversed."); if (!string.Equals(shipment.ConcurrencyToken, request.ConcurrencyToken, StringComparison.Ordinal)) return TransactionResult.Failure("The supplier-return shipment changed after it was opened. Refresh and review it again."); if (request.ReversalDate < shipment.ShippedOn) return TransactionResult.Failure("The reversal date cannot precede the shipment date."); if (shipment.AppliedAmount != shipment.SourceAppliedAmount || shipment.RefundedAmount != 0m || await db.SupplierReturnCreditApplications.AnyAsync(item => item.CompanyId == companyId && item.SupplierReturnShipmentId == shipment.Id && item.Status == "Posted", cancellationToken) || await db.SupplierReturnCreditRefunds.AnyAsync(item => item.CompanyId == companyId && item.SupplierReturnShipmentId == shipment.Id && item.Status == "Posted", cancellationToken)) return TransactionResult.Failure("Reverse all later supplier-credit applications and refunds before reversing the physical return.");
        var authorization = await db.SupplierReturnAuthorizations.SingleAsync(item => item.Id == shipment.SupplierReturnAuthorizationId && item.CompanyId == companyId, cancellationToken); var receipt = await db.InventoryReceipts.SingleAsync(item => item.Id == authorization.InventoryReceiptId && item.CompanyId == companyId, cancellationToken); if (!shipment.CreatesVendorCredit && await db.VendorBills.AnyAsync(item => item.CompanyId == companyId && item.InventoryReceiptId == receipt.Id && item.Status != "Voided", cancellationToken)) return TransactionResult.Failure("Void the bill matched after this supplier return before reversing its physical shipment.");
        var lines = await db.SupplierReturnShipmentLines.Where(line => line.SupplierReturnShipmentId == shipment.Id).OrderBy(line => line.Sequence).ToListAsync(cancellationToken); var items = await db.InventoryItems.Where(item => item.CompanyId == companyId && lines.Select(line => line.InventoryItemId).Contains(item.Id)).ToDictionaryAsync(item => item.Id, cancellationToken); var finalLineByItem = lines.GroupBy(line => line.InventoryItemId).Select(group => group.OrderByDescending(line => line.Sequence).First()); if (finalLineByItem.Any(line => items[line.InventoryItemId].QuantityOnHand != line.PriorQuantityOnHand - line.Quantity || items[line.InventoryItemId].UnitCost != line.ResultingUnitCost)) return TransactionResult.Failure("This supplier return is no longer the latest valuation event for every item. Post a compensating inventory adjustment instead of rewriting later valuation.");
        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken); var reversal = await PostInverseAsync(db, companyId, shipment.JournalEntryId, request.ReversalDate, $"REV-{shipment.ShipmentNumber}", request.Reason.Trim(), shipment.Id, "SupplierReturnShipmentReversal", null, cancellationToken, "Purchasing"); if (!reversal.Succeeded) return reversal; var authorizationLines = await db.SupplierReturnAuthorizationLines.Where(line => line.SupplierReturnAuthorizationId == authorization.Id).ToDictionaryAsync(line => line.Id, cancellationToken); var receiptLines = await db.InventoryReceiptLines.Where(line => line.InventoryReceiptId == receipt.Id).ToDictionaryAsync(line => line.Id, cancellationToken); var order = await db.PurchaseOrders.SingleAsync(item => item.Id == authorization.PurchaseOrderId && item.CompanyId == companyId, cancellationToken); var orderLines = await db.PurchaseOrderLines.Where(line => line.PurchaseOrderId == order.Id).ToDictionaryAsync(line => line.Id, cancellationToken);
        foreach (var line in lines.OrderByDescending(line => line.Sequence)) { var item = items[line.InventoryItemId]; item.QuantityOnHand = line.PriorQuantityOnHand; item.UnitCost = line.PriorUnitCost; item.ConcurrencyToken = Guid.NewGuid().ToString("N"); var balance = await GetOrCreateInventoryLocationBalanceAsync(db, companyId, line.InventoryItemId, shipment.WarehouseId, shipment.BinId, cancellationToken); balance.QuantityOnHand += line.Quantity; balance.ConcurrencyToken = Guid.NewGuid().ToString("N"); authorizationLines[line.SupplierReturnAuthorizationLineId].ShippedQuantity -= line.Quantity; receiptLines[line.InventoryReceiptLineId].ReturnedQuantity -= line.Quantity; orderLines[line.PurchaseOrderLineId].ReturnedQuantity -= line.Quantity; orderLines[line.PurchaseOrderLineId].CreditedQuantity -= line.InvoicedQuantity; db.InventoryTransactions.Add(new InventoryTransaction { Id = Guid.NewGuid(), CompanyId = companyId, InventoryItemId = line.InventoryItemId, WarehouseId = shipment.WarehouseId, BinId = shipment.BinId, OccurredOn = request.ReversalDate, TransactionType = "Supplier return reversal", QuantityChange = line.Quantity, UnitCost = line.UnitCost, TotalCost = line.TotalAmount, Reference = $"REV-{shipment.ShipmentNumber}", JournalEntryId = reversal.Id }); }
        if (shipment.CreatesVendorCredit) { var bill = await db.VendorBills.SingleAsync(item => item.Id == shipment.SourceVendorBillId && item.CompanyId == companyId, cancellationToken); bill.BalanceDue += shipment.SourceAppliedAmount; bill.Status = bill.BalanceDue == bill.TotalAmount ? "Open" : "Partial"; bill.ConcurrencyToken = Guid.NewGuid().ToString("N"); (await db.Vendors.SingleAsync(item => item.Id == authorization.VendorId && item.CompanyId == companyId, cancellationToken)).OpenBalance += shipment.VendorCreditAmount; }
        authorization.Status = authorizationLines.Values.All(line => line.ShippedQuantity == 0m) ? "Open" : authorizationLines.Values.All(line => line.ShippedQuantity == line.AuthorizedQuantity) ? "Shipped" : "PartiallyShipped"; authorization.ConcurrencyToken = Guid.NewGuid().ToString("N"); receipt.ConcurrencyToken = Guid.NewGuid().ToString("N"); shipment.Status = "Reversed"; shipment.ReversalJournalEntryId = reversal.Id; shipment.ReversedByUserId = ResolveUserId(); shipment.ReversedAtUtc = DateTimeOffset.UtcNow; shipment.ReversalDate = request.ReversalDate; shipment.ReversalReason = request.Reason.Trim(); shipment.ConcurrencyToken = Guid.NewGuid().ToString("N"); SetPurchaseOrderReturnStatus(order, orderLines.Values); AddPurchasingAudit(db, companyId, "supplier-return.shipment.reversed", nameof(SupplierReturnShipment), shipment.Id, new { shipment.ShipmentNumber, shipment.TotalAmount, shipment.ReversalDate, shipment.ReversalReason });
        try { await db.SaveChangesAsync(cancellationToken); } catch (DbUpdateConcurrencyException) { return TransactionResult.Failure("The supplier return or inventory changed while reversing. Refresh and try again."); }
        await transaction.CommitAsync(cancellationToken); return TransactionResult.Success(shipment.Id);
    }

    private static void SetPurchaseOrderReturnStatus(PurchaseOrder order, IEnumerable<PurchaseOrderLine> lines)
    {
        var materialized = lines.ToArray();
        order.Status = materialized.All(line => line.ReceivedQuantity - line.ReturnedQuantity == line.OrderedQuantity && line.InvoicedQuantity - line.CreditedQuantity == line.OrderedQuantity) ? "Closed" : materialized.All(line => line.ReceivedQuantity - line.ReturnedQuantity == line.OrderedQuantity) ? "Received" : materialized.Any(line => line.ReceivedQuantity - line.ReturnedQuantity > 0m) ? "PartiallyReceived" : "Approved";
        order.ConcurrencyToken = Guid.NewGuid().ToString("N");
    }
